css:
.terminal-container {
  background-color: #101729;
  border-radius: 10px;
  border: 1px solid #1a222f;
  display: flex;
  flex-direction: column;
  padding: 20px;
  max-width: 320px;
  font-family: "Courier New", monospace;
}

.top-side {
  display: flex;
  flex-direction: row;
  align-items: center;
  border-bottom: 1px solid #212b3f;
  padding-bottom: 10px;
  margin-bottom: 20px;
}

.red-circle {
  width: 12px;
  height: 12px;
  background-color: #ef4444;
  border-radius: 50%;
  margin-right: 7px;
}

.yellow-circle {
  width: 12px;
  height: 12px;
  background-color: #eab308;
  border-radius: 50%;
  margin-right: 7px;
}

.green-circle {
  width: 12px;
  height: 12px;
  background-color: #22c55e;
  border-radius: 50%;
  margin-right: 15px;
}

.terminal-title {
  color: #fff;
  margin: 0;
}

.line {
  color: #fff;
}

.line:not(:last-child) {
  margin-bottom: 12px;
}

.dollar {
  color: #2282f4;
  margin-right: 15px;
}

.green-line {
  margin-bottom: 12px;
  color: #46cf79;
}

.line-1 {
  animation: green-color 3s infinite;
}

.line-2 {
  animation: green-color 3.5s infinite;
}

.line-3 {
  animation: green-color 2s infinite;
}

@keyframes green-color {
  0% {
    color: #2a7151;
  }

  50% {
    color: #46cf79;
  }

  100% {
    color: #2a7151;
  }
}
